/**
 * Runtime configuration.
 * Override the VPN API URL with VITE_VPN_API_URL at build time.
 */

function stripTrailingSlash(url: string): string {
  return url.replace(/\/$/, '');
}

const vpnApiUrl = stripTrailingSlash(
  (import.meta.env.VITE_VPN_API_URL as string | undefined) ||
    'https://api.netil.ir/vpn',
);

/** Origin of the Netil API (e.g. https://api.netil.ir). */
function apiOriginFromVpnUrl(url: string): string {
  try {
    return new URL(url).origin;
  } catch {
    return 'https://api.netil.ir';
  }
}

const apiOrigin = apiOriginFromVpnUrl(vpnApiUrl);

export type SpeedEndpoint = {
  id: 'cloudflare' | 'netil';
  downloadUrl: string;
  uploadUrl: string;
  metaUrl: string;
};

export const config = {
  /** Cloudflare Worker endpoint that returns a boolean VPN status. */
  vpnApiUrl,
  apiOrigin,

  /**
   * Speed-test backends. Cloudflare is preferred when reachable;
   * Netil Worker is the Iran-friendly fallback (api.netil.ir).
   */
  speed: {
    endpoints: [
      {
        id: 'cloudflare',
        downloadUrl: 'https://speed.cloudflare.com/__down',
        uploadUrl: 'https://speed.cloudflare.com/__up',
        metaUrl: 'https://speed.cloudflare.com/meta',
      },
      {
        id: 'netil',
        downloadUrl: `${apiOrigin}/speed/down`,
        uploadUrl: `${apiOrigin}/speed/up`,
        metaUrl: `${apiOrigin}/speed/meta`,
      },
    ] satisfies SpeedEndpoint[],
    pingSamples: 6,
    downloadBytes: [1_000_000, 5_000_000, 10_000_000],
    uploadBytes: [1_000_000, 2_500_000, 5_000_000],
    probeTimeoutMs: 4000,
  },
} as const;
