import { config, type SpeedEndpoint } from '../config';

export type SpeedPhase = 'idle' | 'ping' | 'download' | 'upload' | 'done' | 'error';

export interface SpeedProgress {
  phase: SpeedPhase;
  pingMs: number | null;
  downloadMbps: number | null;
  uploadMbps: number | null;
  provider: string | null;
  /** Which backend is serving the test */
  endpointId: SpeedEndpoint['id'] | null;
  /** 0–100 overall progress for the gauge / progress bar */
  progress: number;
  /** Instantaneous Mbps during download/upload, for live gauge */
  liveMbps: number | null;
}

export type SpeedListener = (state: SpeedProgress) => void;

function median(values: number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1]! + sorted[mid]!) / 2
    : sorted[mid]!;
}

function toMbps(bytes: number, durationMs: number): number {
  if (durationMs <= 0) return 0;
  return (bytes * 8) / (durationMs / 1000) / 1_000_000;
}

function asNonEmptyString(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function formatProvider(org: string | null, asn: unknown): string | null {
  if (!org) return null;
  if (typeof asn === 'number' || typeof asn === 'string') {
    return `${org} (AS${asn})`;
  }
  return org;
}

async function probeEndpoint(endpoint: SpeedEndpoint): Promise<boolean> {
  const controller = new AbortController();
  const timer = window.setTimeout(
    () => controller.abort(),
    config.speed.probeTimeoutMs,
  );

  try {
    const url = `${endpoint.downloadUrl}?bytes=0&r=${Math.random()}`;
    const res = await fetch(url, {
      cache: 'no-store',
      mode: 'cors',
      signal: controller.signal,
    });
    if (!res.ok) return false;
    await res.arrayBuffer();
    return true;
  } catch {
    return false;
  } finally {
    window.clearTimeout(timer);
  }
}

async function selectEndpoint(): Promise<SpeedEndpoint> {
  for (const endpoint of config.speed.endpoints) {
    if (await probeEndpoint(endpoint)) {
      return endpoint;
    }
  }
  throw new Error('No reachable speed-test endpoint');
}

async function fetchProvider(endpoint: SpeedEndpoint): Promise<string | null> {
  try {
    const res = await fetch(endpoint.metaUrl, {
      cache: 'no-store',
      mode: 'cors',
      headers: { Accept: 'application/json' },
    });
    if (!res.ok) return null;
    const data = (await res.json()) as {
      asOrganization?: unknown;
      asn?: unknown;
    };
    return formatProvider(asNonEmptyString(data.asOrganization), data.asn);
  } catch {
    return null;
  }
}

async function measurePing(
  endpoint: SpeedEndpoint,
  samples: number,
): Promise<number> {
  const times: number[] = [];

  for (let i = 0; i < samples; i++) {
    const url = `${endpoint.downloadUrl}?bytes=0&r=${Math.random()}`;
    const start = performance.now();
    const res = await fetch(url, { cache: 'no-store', mode: 'cors' });
    await res.arrayBuffer();
    times.push(performance.now() - start);
  }

  return median(times);
}

async function measureDownload(
  endpoint: SpeedEndpoint,
  sizes: readonly number[],
  onLive: (mbps: number, fraction: number) => void,
): Promise<number> {
  const rates: number[] = [];

  for (let i = 0; i < sizes.length; i++) {
    const bytes = sizes[i]!;
    const url = `${endpoint.downloadUrl}?bytes=${bytes}&r=${Math.random()}`;
    const start = performance.now();
    const res = await fetch(url, { cache: 'no-store', mode: 'cors' });
    if (!res.ok || !res.body) throw new Error(`download failed: ${res.status}`);

    const reader = res.body.getReader();
    let received = 0;

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      received += value.byteLength;
      const elapsed = performance.now() - start;
      const live = toMbps(received, elapsed);
      const stepFraction = (i + received / bytes) / sizes.length;
      onLive(live, stepFraction);
    }

    rates.push(toMbps(received, performance.now() - start));
  }

  return rates.length === 1 ? rates[0]! : median(rates.slice(1));
}

async function measureUpload(
  endpoint: SpeedEndpoint,
  sizes: readonly number[],
  onLive: (mbps: number, fraction: number) => void,
): Promise<number> {
  const rates: number[] = [];

  for (let i = 0; i < sizes.length; i++) {
    const bytes = sizes[i]!;
    const payload = new Uint8Array(bytes);
    const start = performance.now();

    const tick = window.setInterval(() => {
      const elapsed = performance.now() - start;
      const assumed = Math.min(bytes, (bytes * elapsed) / Math.max(elapsed + 500, 1));
      onLive(toMbps(assumed, elapsed), (i + Math.min(elapsed / 2000, 0.95)) / sizes.length);
    }, 120);

    const res = await fetch(`${endpoint.uploadUrl}?r=${Math.random()}`, {
      method: 'POST',
      body: payload,
      mode: 'cors',
      headers: { 'Content-Type': 'application/octet-stream' },
    });

    window.clearInterval(tick);
    if (!res.ok) throw new Error(`upload failed: ${res.status}`);
    await res.arrayBuffer();

    const mbps = toMbps(bytes, performance.now() - start);
    rates.push(mbps);
    onLive(mbps, (i + 1) / sizes.length);
  }

  return rates.length === 1 ? rates[0]! : median(rates.slice(1));
}

export async function runSpeedTest(onProgress: SpeedListener): Promise<void> {
  const emit = (partial: Partial<SpeedProgress> & Pick<SpeedProgress, 'phase'>) => {
    onProgress({
      pingMs: null,
      downloadMbps: null,
      uploadMbps: null,
      provider: null,
      endpointId: null,
      progress: 0,
      liveMbps: null,
      ...partial,
    });
  };

  let pingMs: number | null = null;
  let downloadMbps: number | null = null;
  let uploadMbps: number | null = null;
  let provider: string | null = null;
  let endpointId: SpeedEndpoint['id'] | null = null;

  try {
    emit({ phase: 'ping', progress: 1 });
    const endpoint = await selectEndpoint();
    endpointId = endpoint.id;

    const providerPromise = fetchProvider(endpoint).then((value) => {
      provider = value;
      return value;
    });

    emit({ phase: 'ping', endpointId, provider, progress: 4 });
    pingMs = await measurePing(endpoint, config.speed.pingSamples);
    provider = await providerPromise;
    emit({ phase: 'ping', pingMs, provider, endpointId, progress: 12 });

    emit({ phase: 'download', pingMs, provider, endpointId, progress: 15 });
    downloadMbps = await measureDownload(
      endpoint,
      config.speed.downloadBytes,
      (live, frac) => {
        emit({
          phase: 'download',
          pingMs,
          provider,
          endpointId,
          downloadMbps: live,
          liveMbps: live,
          progress: 15 + frac * 45,
        });
      },
    );
    emit({
      phase: 'download',
      pingMs,
      provider,
      endpointId,
      downloadMbps,
      liveMbps: downloadMbps,
      progress: 60,
    });

    emit({
      phase: 'upload',
      pingMs,
      downloadMbps,
      provider,
      endpointId,
      progress: 62,
    });
    uploadMbps = await measureUpload(
      endpoint,
      config.speed.uploadBytes,
      (live, frac) => {
        emit({
          phase: 'upload',
          pingMs,
          downloadMbps,
          provider,
          endpointId,
          uploadMbps: live,
          liveMbps: live,
          progress: 62 + frac * 35,
        });
      },
    );

    emit({
      phase: 'done',
      pingMs,
      downloadMbps,
      uploadMbps,
      provider,
      endpointId,
      liveMbps: null,
      progress: 100,
    });
  } catch {
    emit({
      phase: 'error',
      pingMs,
      downloadMbps,
      uploadMbps,
      provider,
      endpointId,
      liveMbps: null,
      progress: 0,
    });
  }
}
